1	#!/usr/bin/env node
2	import { readFileSync } from 'node:fs';
3	import process from 'node:process';
4	
5	const forbidden = new Set(['gap', 'row-gap', 'column-gap', 'float', 'filter', 'backdrop-filter', 'background', 'background-image', 'box-shadow', 'outline', 'text-overflow', 'white-space', 'word-break', 'transition', 'animation']);
6	const bem = /^\.[a-z][a-z0-9]*(?:-[a-z0-9]+)*(?:__(?:[a-z0-9]+(?:-[a-z0-9]+)*))?(?:--[a-z0-9]+(?:-[a-z0-9]+)*)?$/;
7	
8	function issue(file, line, rule, message) {
9	  return `${file}:${line} [${rule}] ${message}`;
10	}
11	
12	function validate(file) {
13	  const errors = [];
14	  const lines = readFileSync(file, 'utf8').split(/\r?\n/);
15	  let depth = 0;
16	  for (let index = 0; index < lines.length; index += 1) {
17	    const line = lines[index].trim();
18	    const number = index + 1;
19	    const selector = line.match(/^(.+?)\s*\{$/);
20	    if (selector) {
21	      if (depth > 0) errors.push(issue(file, number, 'top-level-single-selector', '公共 Less 不允许嵌套规则'));
22	      if (!bem.test(selector[1].trim())) errors.push(issue(file, number, 'bem-selector', '选择器必须是单个 BEM 类'));
23	      depth += 1;
24	      continue;
25	    }
26	    if (line === '}') {
27	      depth -= 1;
28	      if (depth < 0) errors.push(issue(file, number, 'syntax', '存在未匹配的 }'));
29	      continue;
30	    }
31	    const declaration = line.match(/^([a-z-]+)\s*:\s*([^;]+);?$/i);
32	    if (!declaration) continue;
33	    const property = declaration[1].toLowerCase();
34	    const value = declaration[2].trim();
35	    if (forbidden.has(property)) errors.push(issue(file, number, 'forbidden-property', `${property} 不允许用于公共 Less`));
36	    if (property === 'line-height' && !/^-?\d+(?:\.\d+)?px$/i.test(value)) errors.push(issue(file, number, 'line-height-px', 'line-height 必须为 px 数值'));
37	    if (/\b(?:calc|var)\s*\(/.test(value) || /\b\d+(?:\.\d+)?(?:vh|vw|em|rem|rpx)\b/.test(value)) errors.push(issue(file, number, 'forbidden-unit', '公共 Less 不允许该单位或函数'));
38	  }
39	  if (depth !== 0) errors.push(issue(file, lines.length, 'syntax', '规则括号不匹配'));
40	  return errors;
41	}
42	
43	const files = process.argv.slice(2);
44	if (files.length === 0) {
45	  console.error('[file] 必须提供 Less 文件');
46	  process.exit(1);
47	}
48	const errors = files.flatMap(validate);
49	if (errors.length) {
50	  console.error(errors.join('\n'));
51	  process.exit(1);
52	}
53	console.log(`PASS ${files.length} 个 Less 文件`);
54

